#!/usr/bin/env python3
"""Exercise the real migration CLI against an explicitly supplied empty PG18 test DB.

Requires CVM_MIGRATION_BIN, protected primary/migration URL environment variables,
and libpq PG* settings for the same database (PGDATABASE must start cvm_direct_test).
Never uses production data or creates/drops a database.
"""
import json
import os
from pathlib import Path
import sqlite3
import subprocess
import tempfile
import re
import time
import urllib.request


def sql(statement):
    return subprocess.check_output(["psql", "-XAt", "-v", "ON_ERROR_STOP=1", "-c", statement], text=True).strip()


def main():
    assert os.environ["PGDATABASE"].startswith("cvm_direct_test"), "explicit test database required"
    assert sql("SELECT count(*) FROM information_schema.tables WHERE table_schema NOT IN ('pg_catalog','information_schema')") == "0", "requires empty test DB"
    binary = os.environ["CVM_MIGRATION_BIN"]
    with tempfile.TemporaryDirectory(prefix="cvm-direct-source-") as directory:
        root = Path(directory)
        database = root / "codex_vibe_monitor.db"
        connection = sqlite3.connect(database)
        connection.executescript("""
            CREATE TABLE parent(id INTEGER PRIMARY KEY, label TEXT, payload BLOB, amount REAL);
            CREATE UNIQUE INDEX unique_label ON parent(label) WHERE label IS NOT NULL;
            CREATE TABLE child(id INTEGER PRIMARY KEY, parent_id INTEGER REFERENCES parent(id));
            CREATE TABLE composite(tenant TEXT, id INTEGER, value TEXT, PRIMARY KEY(id,tenant)) WITHOUT ROWID;
            CREATE TABLE unkeyed(value TEXT, count INTEGER);
            CREATE TABLE nullable_key(id TEXT PRIMARY KEY, value TEXT);
            CREATE TABLE empty(id INTEGER PRIMARY KEY);
            CREATE TABLE pool_upstream_accounts(id INTEGER PRIMARY KEY,kind TEXT,display_name TEXT,enabled INTEGER,group_name TEXT,deleted_at TEXT);
            INSERT INTO pool_upstream_accounts VALUES(1,'oauth','fixture-account',1,NULL,NULL);
        """)
        connection.executemany("INSERT INTO parent VALUES(?,?,?,?)", [(i, f"label-{i}", bytes([0, 255, i]), i/10) for i in range(1,8)])
        connection.execute("INSERT INTO child VALUES(1,1)")
        connection.executemany("INSERT INTO composite VALUES(?,?,?)", [("a'b",1,'comma,quote"\n'),('z',1,''),('a',2,None)])
        connection.executemany("INSERT INTO unkeyed VALUES(?,?)", [('same',1),('same',1),(None,2),('',3)])
        connection.executemany("INSERT INTO nullable_key VALUES(?,?)", [(None,'null-key'),('key','value')])
        connection.commit()
        env = os.environ.copy()
        env.update(PRIMARY_DATABASE_BACKEND="postgres", MIGRATION_SNAPSHOT_PATH=str(database), MIGRATION_SKIP_SOURCE_COUNTS="1")
        profile = ["--target-profile", "direct-test", "--run-id", "test"]
        def cli(*args, ok=True):
            result = subprocess.run([binary,"migrate",*args], env=env, text=True, capture_output=True)
            if ok and result.returncode:
                raise AssertionError(result.stderr[-4000:])
            if not ok:
                assert result.returncode, "expected rejection"
            return result
        manifest = str(root / "manifest.json")
        cli("inspect-source","--source-root",directory,"--manifest-out",manifest)
        cli("prepare",*profile,"--source-manifest",manifest)
        # Fail the second parent batch through a real PG trigger. The first COPY
        # and its checkpoint must survive, while the failing batch rolls back.
        sql("CREATE TABLE cvm_core.parent(id BIGINT GENERATED BY DEFAULT AS IDENTITY,label TEXT,payload BYTEA,amount DOUBLE PRECISION)")
        sql("CREATE FUNCTION cvm_core.fail_batch() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.id=3 THEN RAISE EXCEPTION 'injected batch failure'; END IF; RETURN NEW; END $$")
        sql("CREATE TRIGGER fail_batch BEFORE INSERT ON cvm_core.parent FOR EACH ROW EXECUTE FUNCTION cvm_core.fail_batch()")
        cli("seed",*profile,"--source-root",directory,"--batch-rows","2",ok=False)
        assert sql("SELECT count(*) FROM cvm_core.parent") == "2"
        sql("DROP TRIGGER fail_batch ON cvm_core.parent")
        cli("resume",*profile,"--batch-rows","2")
        assert sql("SELECT count(*) FROM information_schema.columns WHERE table_schema LIKE 'cvm_%' AND column_name IN ('_cvm_payload','_cvm_source_key','_cvm_run_id')") == "0"
        assert sql("SELECT to_regclass('cvm_migration.imported_rows') IS NULL AND to_regclass('cvm_migration.row_staging') IS NULL") == "t"
        assert sql("SELECT encode(payload,'hex') FROM cvm_core.parent WHERE id=1") == "00ff01"
        # Interrupt after committed batches, then resume without duplicating rows.
        sql("UPDATE cvm_migration.runs SET state='seeding' WHERE run_id='test'")
        cli("resume",*profile,"--batch-rows","2")
        # Same row count, changed content must be detected independently of counts.
        sql("UPDATE cvm_core.parent SET label='corrupted' WHERE id=2")
        sql("UPDATE cvm_migration.runs SET state='verified' WHERE run_id='test'")
        cli("verify",*profile,"--strict",ok=False)
        sql("UPDATE cvm_core.parent SET label='label-2' WHERE id=2")
        sql("UPDATE cvm_migration.runs SET state='seeded' WHERE run_id='test'")
        unchanged_ctid = sql("SELECT ctid::text FROM cvm_core.parent WHERE id=1")
        cli("mark-source-stopped",*profile)
        # Deletes in the middle and tail, new keys before and after the old range,
        # changed value at equal row count, composite keys and unkeyed duplicates.
        connection.execute("DELETE FROM parent WHERE id IN (3,7)")
        connection.execute("UPDATE parent SET label='changed' WHERE id=2")
        connection.executemany("INSERT INTO parent VALUES(?,?,?,?)", [(0,'before',b'\x80',None),(9,'after',b'',0)])
        connection.execute("DELETE FROM composite WHERE tenant='z'")
        connection.execute("UPDATE composite SET value='updated' WHERE id=2")
        connection.execute("DELETE FROM unkeyed WHERE count=3")
        connection.execute("UPDATE nullable_key SET value='changed-null' WHERE id IS NULL")
        connection.commit()
        cli("catch-up",*profile,"--source-root",directory,"--batch-rows","2")
        cli("verify",*profile,"--strict")
        assert sql("SELECT ctid::text FROM cvm_core.parent WHERE id=1") == unchanged_ctid, "unchanged rows must not be rewritten"
        assert sql("SELECT string_agg(id::text,',' ORDER BY id) FROM cvm_core.parent") == "0,1,2,4,5,6,9"
        assert sql("SELECT label FROM cvm_core.parent WHERE id=2") == "changed"
        assert sql("SELECT value FROM cvm_core.nullable_key WHERE id IS NULL") == "changed-null"
        cli("finalize",*profile)
        cli("verify",*profile,"--strict")
        env["MIGRATION_MAX_TARGET_BYTES"]="1"
        cli("verify",*profile,ok=False)
        env.pop("MIGRATION_MAX_TARGET_BYTES")
        connection.close()
        sql("GRANT USAGE ON SCHEMA cvm_core,cvm_activity,cvm_stats,cvm_archive,cvm_assets,cvm_migration TO cvm_app")
        for schema in ['cvm_core','cvm_activity','cvm_stats','cvm_archive','cvm_assets','cvm_migration']:
            sql(f"GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA {schema} TO cvm_app")
            sql(f"GRANT USAGE,SELECT,UPDATE ON ALL SEQUENCES IN SCHEMA {schema} TO cvm_app")
        env.update(HTTP_BIND="127.0.0.1:0",DATABASE_PATH=str(root/'must-not-open.sqlite'),RUST_LOG="info",NO_COLOR="1")
        # This is a bounded guest-only HTTP regression. The kernel assigns its
        # port; no host mapping or long-lived preview is created.
        for restart in range(2):
            log = root / f'runtime-{restart}.log'
            with log.open('w') as output:
                process = subprocess.Popen([binary],env=env,cwd=directory,stdout=output,stderr=subprocess.STDOUT)
                try:
                    address = None
                    for _ in range(100):
                        if process.poll() is not None:
                            raise AssertionError(log.read_text()[-4000:])
                        match = re.search(r'address=(127\.0\.0\.1:[0-9]+)',log.read_text())
                        if match: address=match.group(1);break
                        time.sleep(.1)
                    assert address, 'HTTP readiness timeout'
                    def http(path,method='GET',payload=None):
                        data=None if payload is None else json.dumps(payload).encode()
                        request=urllib.request.Request('http://'+address+path,data=data,method=method,headers={'Content-Type':'application/json'})
                        with urllib.request.urlopen(request,timeout=10) as response:
                            body=response.read()
                            return json.loads(body) if body else None
                    account=http('/api/pool/upstream-accounts/1')
                    assert account['displayName']==('fixture-account' if restart==0 else 'persisted-name')
                    if restart==0:
                        http('/api/pool/upstream-accounts/1','PATCH',{'displayName':'persisted-name'})
                        http('/api/pool/upstream-accounts/1','PATCH',{'enabled':False})
                        assert sql('SELECT enabled FROM cvm_core.pool_upstream_accounts WHERE id=1')=='0'
                    assert not (root/'must-not-open.sqlite').exists()
                finally:
                    process.terminate()
                    process.wait(timeout=10)
        print(json.dumps({"passed":True,"native_columns":True,"seed_resume":True,"catch_up_deletes_updates_inserts":True,"strict_detects_corruption":True,"pg_only_api_read_write_restart":True}))

if __name__ == "__main__":
    main()
